def prime_factorization(n):
    factors = {}
    d = 2
    temp = n
    while d * d <= temp:
        while temp % d == 0:
            factors[d] = factors.get(d, 0) + 1
            temp //= d
        d += 1
    if temp > 1:
        factors[temp] = factors.get(temp, 0) + 1
    return factors

def tau_squared(factors):
    tau = 1
    for exponent in factors.values():
        tau *= (2 * exponent + 1)
    return tau

x_candidates = [1680, 1260, 1440] # Testing the current best and related highly composite numbers near the limit
results = {}

for x in x_candidates:
    factors = prime_factorization(x)
    tau_x2 = tau_squared(factors)
    results[x] = tau_x2

print("Tau(x^2) for tested candidates:")
print(results)
